import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { ApiService } from '../../services/api.service';

@Component({
  selector: 'app-report-incident',
  template: `
    <div class="report-wrapper">
      <div class="glass-card report-card animate-fade-in">
        <h2>Relatar Incidente</h2>
        <p class="subtitle">Sua colaboração ajuda a manter o bairro seguro</p>

        <form (submit)="onSubmit()" class="mt-8">
          <div class="input-group">
            <label>Descrição</label>
            <textarea [(ngModel)]="incident.description" name="description" rows="4" required placeholder="O que aconteceu?"></textarea>
          </div>

          <div class="input-group">
            <label>Nível de Gravidade</label>
            <select [(ngModel)]="incident.severity_level" name="severity_level" required>
              <option value="LOW">Baixo</option>
              <option value="MEDIUM">Médio</option>
              <option value="HIGH">Alto</option>
            </select>
          </div>

          <div class="grid-2 gap-4">
            <div class="input-group">
              <label>Latitude</label>
              <input type="number" step="0.000001" [(ngModel)]="incident.location.latitude" name="latitude" required>
            </div>
            <div class="input-group">
              <label>Longitude</label>
              <input type="number" step="0.000001" [(ngModel)]="incident.location.longitude" name="longitude" required>
            </div>
          </div>

          <button type="submit" class="btn btn-primary w-full">Enviar Relato</button>
        </form>
      </div>
    </div>
  `,
  styles: [`
    .report-wrapper {
      display: flex;
      justify-content: center;
      padding: 2rem 0;
    }
    .report-card {
      width: 100%;
      max-width: 600px;
      padding: 2.5rem;
    }
    .subtitle {
      color: var(--text-muted);
      font-size: 0.875rem;
    }
    .grid-2 {
      display: grid;
      grid-template-columns: 1fr 1fr;
    }
    .w-full { width: 100%; }
  `]
})
export class ReportIncidentComponent {
  incident = {
    description: '',
    severity_level: 'LOW',
    location: {
      latitude: -23.550520,
      longitude: -46.633308
    }
  };

  constructor(private api: ApiService, private router: Router) {}

  onSubmit() {
    this.api.createIncident(this.incident).subscribe({
      next: () => {
        alert('Incidente relatado com sucesso!');
        this.router.navigate(['/']);
      },
      error: (err) => {
        const error = err.error?.non_field_errors?.[0] || 'Erro ao relatar incidente';
        alert(error);
        if (error.includes('perfil deve estar completo')) {
          this.router.navigate(['/profile']);
        }
      }
    });
  }
}
